import { KANJI_N5, type JlptLevel, type KanjiChar } from "./characters";

// Generated by scripts/build-kanji-data.mjs from KANJIDIC (davidluzgouveia/kanji-data, MIT).
const LOADERS: Record<JlptLevel, () => Promise<{ default: KanjiChar[] }>> = {
  N5: () => import("./kanji/n5.json") as Promise<{ default: KanjiChar[] }>,
  N4: () => import("./kanji/n4.json") as Promise<{ default: KanjiChar[] }>,
  N3: () => import("./kanji/n3.json") as Promise<{ default: KanjiChar[] }>,
  N2: () => import("./kanji/n2.json") as Promise<{ default: KanjiChar[] }>,
  N1: () => import("./kanji/n1.json") as Promise<{ default: KanjiChar[] }>,
};

// Level IDs follow the `levels` table seed; PEMULA starts on N5 kanji.
const LEVEL_BY_ID: Record<number, JlptLevel> = { 1: "N5", 2: "N5", 3: "N4", 4: "N3", 5: "N2", 6: "N1" };

export function kanjiLevelFor(levelId: number | null | undefined): JlptLevel {
  return (levelId != null && LEVEL_BY_ID[levelId]) || "N5";
}

const curated = new Map(KANJI_N5.map((k) => [k.character, k]));

export async function loadKanji(level: JlptLevel): Promise<KanjiChar[]> {
  const { default: list } = await LOADERS[level]();
  return list.map((k) => {
    const c = curated.get(k.character);
    return c ? { ...k, ...c, meaningEn: k.meaningEn, level: k.level } : k;
  });
}
